import Link from 'next/link'
import { Button } from '@/registry/bases/radix/veil/ui/button'
import { Card } from '@/registry/bases/radix/veil/ui/card'
import { Check, Minus } from 'lucide-react'

const plans = [
    {
        name: 'Basic',
        price: '$9',
        period: '/month',
        cta: 'Get Started',
    },
    {
        name: 'Pro',
        price: '$29',
        period: '/month',
        cta: 'Start Free Trial',
        highlighted: true,
    },
    {
        name: 'Team',
        price: '$79',
        period: '/month',
        cta: 'Start Free Trial',
    },
]

const features = [
    { name: 'Integrations', basic: '5', pro: 'Unlimited', team: 'Unlimited' },
    { name: 'API Calls', basic: '10K/mo', pro: '100K/mo', team: '1M/mo' },
    { name: 'Team Members', basic: '1', pro: '5', team: 'Unlimited' },
    { name: 'Support', basic: 'Email', pro: 'Priority', team: 'Dedicated' },
    { name: 'Analytics', basic: true, pro: true, team: true },
    { name: 'Custom Webhooks', basic: false, pro: true, team: true },
    { name: 'SSO', basic: false, pro: false, team: true },
    { name: 'Audit Logs', basic: false, pro: false, team: true },
]

export default function Comparator() {
    return (
        <section className="bg-background @container py-24">
            <div className="mx-auto max-w-3xl px-6">
                <div className="text-center">
                    <h2 className="text-balance font-serif text-4xl font-medium">Compare Plans</h2>
                    <p className="text-muted-foreground mx-auto mt-4 max-w-md text-balance">Find the perfect plan for your team's needs.</p>
                </div>
                <Card
                    variant="outline"
                    className="*:min-w-xl mt-12 overflow-auto"
                >
                    <div className="grid grid-cols-4 border-b">
                        <div className="p-4"></div>
                        {plans.map((plan) => (
                            <div
                                key={plan.name}
                                className={`border-l p-4 text-center ${plan.highlighted ? 'bg-primary/5' : ''}`}
                            >
                                <p className="text-foreground font-medium">{plan.name}</p>
                                <p className="mt-1">
                                    <span className="font-serif text-2xl font-medium">{plan.price}</span>
                                    <span className="text-muted-foreground text-sm">{plan.period}</span>
                                </p>
                            </div>
                        ))}
                    </div>
                    {features.map((feature) => (
                        <div
                            key={feature.name}
                            className="grid grid-cols-4 border-b last:border-b-0"
                        >
                            <div className="text-muted-foreground p-4 text-sm">{feature.name}</div>
                            {['basic', 'pro', 'team'].map((plan, idx) => {
                                const value = feature[plan as keyof typeof feature]
                                return (
                                    <div
                                        key={plan}
                                        className={`flex items-center justify-center border-l p-4 text-sm ${idx === 1 ? 'bg-primary/5' : ''}`}
                                    >
                                        {typeof value === 'boolean' ? value ? <Check className="text-primary size-4" /> : <Minus className="text-muted-foreground size-4" /> : <span className="text-foreground">{value}</span>}
                                    </div>
                                )
                            })}
                        </div>
                    ))}
                    <div className="grid grid-cols-4 border-t">
                        <div className="p-4"></div>
                        {plans.map((plan) => (
                            <div
                                key={plan.name}
                                className={`border-l p-4 ${plan.highlighted ? 'bg-primary/5' : ''}`}
                            >
                                <Button
                                    asChild
                                    variant={plan.highlighted ? 'default' : 'outline'}
                                    size="sm"
                                    className="w-full"
                                >
                                    <Link href="#link">{plan.cta}</Link>
                                </Button>
                            </div>
                        ))}
                    </div>
                </Card>
            </div>
        </section>
    )
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/registry/core/lib/utils'

const buttonVariants = cva('cursor-pointer active:scale-99 duration-200 font-medium inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-full text-sm font-medium focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0', {
    variants: {
        variant: {
            default: 'bg-foreground text-background hover:brightness-95',
            neutral: 'bg-foreground text-background hover:brightness-95',
            destructive: 'bg-destructive text-destructive-foreground shadow-md hover:bg-destructive/90',
            outline: 'shadow-sm text-foreground shadow-black/6.5 border border-transparent bg-card ring-1 ring-foreground/15 duration-200 hover:bg-muted/50',
            secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
            ghost: 'hover:bg-foreground/5 text-foreground/75 hover:text-foreground',
            link: 'text-primary underline-offset-4 hover:underline',
        },
        size: {
            default: 'h-8 px-3 py-2',
            sm: 'h-7 px-2.5 text-sm',
            lg: 'h-11 px-6 font-medium text-base',
            icon: 'size-9',
        },
    },
    defaultVariants: {
        variant: 'default',
        size: 'default',
    },
})

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
    asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
        <Comp
            className={cn(buttonVariants({ variant, size, className }))}
            ref={ref}
            {...props}
        />
    )
})
Button.displayName = 'Button'

export { Button, buttonVariants }

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/registry/core/lib/utils'

const cardVariants = cva('text-card-foreground rounded-2xl', {
    variants: {
        variant: {
            default: 'bg-card ring-1 ring-foreground/6.5 shadow-lg shadow-foreground/5 dark:shadow-black/10',
            soft: 'bg-muted',
            mixed: 'bg-muted border',
            outline: 'bg-card ring-1 ring-border',
        },
    },
    defaultVariants: {
        variant: 'default',
    },
})

export interface CardProps extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof cardVariants> {}

const Card = React.forwardRef<HTMLDivElement, CardProps>(({ className, variant, ...props }, ref) => (
    <div
        ref={ref}
        className={cn(cardVariants({ variant, className }))}
        {...props}
    />
))
Card.displayName = 'Card'

const CardHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('flex flex-col space-y-1.5 p-6', className)}
        {...props}
    />
))
CardHeader.displayName = 'CardHeader'

const CardTitle = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('font-semibold leading-none tracking-tight', className)}
        {...props}
    />
))
CardTitle.displayName = 'CardTitle'

const CardDescription = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('text-muted-foreground text-sm', className)}
        {...props}
    />
))
CardDescription.displayName = 'CardDescription'

const CardContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('p-6 pt-0', className)}
        {...props}
    />
))
CardContent.displayName = 'CardContent'

const CardFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('flex items-center p-6 pt-0', className)}
        {...props}
    />
))
CardFooter.displayName = 'CardFooter'

export { Card, CardHeader, CardFooter, CardTitle, CardDescription, CardContent }

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

